class Tests {
    @Test
    fun testMultipleScores() {
        Assert.assertEquals(72, findHighestScore(listOf(45, 72, 38)))
    }

    @Test
    fun testSingleScore() {
        Assert.assertEquals(100, findHighestScore(listOf(100)))
    }

    @Test
    fun testAllSame() {
        Assert.assertEquals(5, findHighestScore(listOf(5, 5, 5)))
    }

    @Test
    fun testHighestAtEnd() {
        Assert.assertEquals(91, findHighestScore(listOf(45, 72, 38, 91)))
    }
